-- Full feed catalog extracted from 葵花日粮计算（九版）.xlsx.
-- Set these two variables before running in another farm.
SET @farm_id = COALESCE(@farm_id, 2081278274962812929);
SET @user_id = COALESCE(@user_id, 2081278274962812930);

ON DUPLICATE KEY UPDATE
  ingredient_type = VALUES(ingredient_type),
  dry_matter_pct = COALESCE(feed_ingredient.dry_matter_pct, VALUES(dry_matter_pct)),
  tdn_pct = COALESCE(feed_ingredient.tdn_pct, VALUES(tdn_pct)),
  crude_protein_pct = COALESCE(feed_ingredient.crude_protein_pct, VALUES(crude_protein_pct)),
  starch_pct = COALESCE(feed_ingredient.starch_pct, VALUES(starch_pct)),
  energy_value = COALESCE(feed_ingredient.energy_value, VALUES(energy_value)),
  gain_energy_value = COALESCE(feed_ingredient.gain_energy_value, VALUES(gain_energy_value)),
  ndf_pct = COALESCE(feed_ingredient.ndf_pct, VALUES(ndf_pct)),
  rdp_pct = COALESCE(feed_ingredient.rdp_pct, VALUES(rdp_pct)),
  unit_price = COALESCE(NULLIF(feed_ingredient.unit_price, 0), VALUES(unit_price)),
  updated_by = @user_id;
